<?php
require_once __DIR__.'/../includes/functions.php';require_admin();$error='';$edit=null;$editId=(int)($_GET['edit']??0);if($editId){$s=$pdo->prepare('SELECT * FROM vocabulary WHERE id=?');$s->execute([$editId]);$edit=$s->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);if($action==='delete'){$s=$pdo->prepare('DELETE FROM vocabulary WHERE id=?');$s->execute([$id]);flash('success','Vocabulary entry deleted.');redirect('admin/vocabulary.php');}$somali=trim($_POST['somali']??'');$english=trim($_POST['english']??'');$definition=trim($_POST['definition']??'');$example=trim($_POST['example_sentence']??'');$category=trim($_POST['category']??'General');$audio=upload_audio('audio_file','vocabulary');if($somali===''||$english==='')throw new RuntimeException('Somali word and English translation are required.');if($id){if($audio){$s=$pdo->prepare('UPDATE vocabulary SET somali=?,english=?,definition=?,example_sentence=?,category=?,audio_path=? WHERE id=?');$s->execute([$somali,$english,$definition,$example,$category,$audio,$id]);}else{$s=$pdo->prepare('UPDATE vocabulary SET somali=?,english=?,definition=?,example_sentence=?,category=? WHERE id=?');$s->execute([$somali,$english,$definition,$example,$category,$id]);}}else{$s=$pdo->prepare('INSERT INTO vocabulary(somali,english,definition,example_sentence,category,audio_path) VALUES(?,?,?,?,?,?)');$s->execute([$somali,$english,$definition,$example,$category,$audio]);}flash('success','Vocabulary entry saved.');redirect('admin/vocabulary.php');}catch(Throwable $e){$error=$e->getMessage();}}
$words=$pdo->query('SELECT id,somali,english,category FROM vocabulary ORDER BY somali LIMIT 300')->fetchAll();$page_title='Manage vocabulary';require __DIR__.'/../includes/admin_header.php';$v=$edit??$_POST;
?>
<div class="admin-heading"><div><span class="eyebrow">DICTIONARY CONTENT</span><h1>Manage vocabulary</h1><p>Add and update Somali–English dictionary entries, examples and pronunciation recordings.</p></div></div><div class="admin-two-col"><section class="admin-panel"><div class="panel-heading"><h2><?= $edit?'Edit word':'Add a word' ?></h2><?php if($edit): ?><a href="<?= url('admin/vocabulary.php') ?>">Cancel</a><?php endif; ?></div><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="admin-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($v['id']??0) ?>"><label>Somali word<input name="somali" required value="<?= e($v['somali']??'') ?>"></label><label>English translation<input name="english" required value="<?= e($v['english']??'') ?>"></label><label>Definition<textarea name="definition" rows="3"><?= e($v['definition']??'') ?></textarea></label><label>Example sentence<textarea name="example_sentence" rows="2"><?= e($v['example_sentence']??'') ?></textarea></label><label>Category<input name="category" value="<?= e($v['category']??'General') ?>"></label><label>Audio pronunciation<input type="file" name="audio_file" accept="audio/*"><small>Optional. MP3, WAV, OGG or M4A; maximum 10 MB.</small></label><button class="btn btn-primary" name="action" value="save">Save word</button></form></section><section class="admin-panel"><div class="panel-heading"><h2>Dictionary entries</h2><span><?= count($words) ?> shown</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Somali</th><th>English</th><th>Category</th><th>Action</th></tr></thead><tbody><?php foreach($words as $w): ?><tr><td><strong><?= e($w['somali']) ?></strong></td><td><?= e($w['english']) ?></td><td><?= e($w['category']) ?></td><td><a href="?edit=<?= (int)$w['id'] ?>">Edit</a><form method="post" class="inline-form" onsubmit="return confirm('Delete this word?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$w['id'] ?>"><button name="action" value="delete" class="link-danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div>
